import { TransformNode, SceneLoader, Vector3 } from '@babylonjs/core';
import { applyModelPaint } from '../../../utils/modelPaint.js';

// Medium doctrine angular turret — ORIGINAL mesh (Panzer III-inspired): 10-facet
// shell, Schuerzen skirt band, rear-center drum cupola, dark external mantlet.
// Generated by scripts/modelgen/medium_turret_angular.py.
// ringDiameter mirrors ringD in params/medium_tank.json.

const PAINT = { paintColor: [0.78, 0.66, 0.43] };

export default {
  id: 'medium-turret-angular',
  name: 'Medium Turret',
  category: 'turret',
  stats: { traverseSpeed: 80 },
  mountEmpty: 'mount',
  defaultCannon: 'medium-gun-50mm',
  paintColor: PAINT.paintColor,

  async build(scene, paintOverride = null) {
    const result = await SceneLoader.ImportMeshAsync('', '/assets/models/tanks/parts/', 'medium_turret_angular.glb', scene);
    const mountNode = result.transformNodes.find(n => n.name === this.mountEmpty);
    const mount = mountNode ? mountNode.getAbsolutePosition().clone() : new Vector3(0, 0.3, 0.95);

    const root = new TransformNode('turret_medium_root', scene);
    const meshes = result.meshes.filter(m => m.name !== '__root__');
    for (const m of meshes) m.setParent(root);
    for (const m of meshes) m.computeWorldMatrix(true);

    applyModelPaint(meshes, PAINT, scene, paintOverride);
    return { root, meshes, mount };
  },
};
